{"file_text": "@page "/settings"
@rendermode InteractiveServer
@using sv_02729721a4c6438b831af27b90ad097a.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">@toastMessage</div>
        }
    </main>
</div>

@* ===== Profile Section ===== *@
@{ RenderFragment ProfileSection = __builder =>
{
    <section class="settings-section">
        <h2>Profile</h2>
        <div class="profile-layout">
            <div class="avatar-area">
                <img src="@profileDisplayName_AvatarUrl" alt="Avatar" class="avatar-preview" />
                <p class="avatar-url">@profileDisplayName_AvatarUrl</p>
            </div>
            <div class="form-fields">
                <div class="field">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="profileDisplayName" />
                </div>
                <div class="field">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="profileEmail" />
                </div>
                <div class="field">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="profileBio"></textarea>
                </div>
                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    </section>
};}

@* ===== Notifications Section ===== *@
@{ RenderFragment NotificationsSection = __builder =>
{
    <section class="settings-section">
        <h2>Notifications</h2>
        <div class="toggle-group">
            <label class="toggle-row">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="notifEmail" />
            </label>
            <label class="toggle-row">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="notifPush" />
            </label>
            <label class="toggle-row">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="notifDigest" />
            </label>
        </div>
        <h3>Muted Channels</h3>
        <div class="channel-list">
            @if (allChannels != null)
            {
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@IsChannelMuted(channel)" @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>#@channel</span>
                    </label>
                }
            }
        </div>
        <div class="button-group">
            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>
};}

@* ===== Security Section ===== *@
@{ RenderFragment SecuritySection = __builder =>
{
    <section class="settings-section">
        <h2>Security</h2>

        <div class="expandable-panel">
            <button class="panel-toggle" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                @(passwordPanelOpen ? "▼" : "▶") Change Password
            </button>
            @if (passwordPanelOpen)
            {
                <div class="panel-content">
                    <div class="field">
                        <label for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" @bind="currentPassword" />
                    </div>
                    <div class="field">
                        <label for="newPwd">New Password</label>
                        <input id="newPwd" type="password" @bind="newPassword" />
                    </div>
                    <div class="field">
                        <label for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" @bind="confirmPassword" />
                    </div>
                    <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="toggle-group" style="margin-top:1.5rem;">
            <label class="toggle-row">
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <input type="checkbox" @bind="twoFactorEnabled" />
            </label>
            @if (securitySettings?.LastPasswordChange != null)
            {
                <p class="meta-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>

        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @if (securitySettings?.Sessions != null)
                {
                    @foreach (var session in securitySettings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != currentSessionId)
                                {
                                    <button class="btn-danger-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>

        @if (showRevokeConfirm)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <p>Revoke session on <strong>@sessionToRevoke?.Device</strong> in @sessionToRevoke?.Location?</p>
                    <div class="button-group">
                        <button class="btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                        <button class="btn-secondary" @onclick="() => showRevokeConfirm = false">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>
};}

@* ===== Appearance Section ===== *@
@{ RenderFragment AppearanceSection = __builder =>
{
    <section class="settings-section">
        <h2>Appearance</h2>

        <div class="field">
            <label>Theme</label>
            <div class="radio-group">
                <label><input type="radio" name="theme" value="Light" checked="@(appearanceTheme == "Light")" @onchange='() => appearanceTheme = "Light"' /> Light</label>
                <label><input type="radio" name="theme" value="Dark" checked="@(appearanceTheme == "Dark")" @onchange='() => appearanceTheme = "Dark"' /> Dark</label>
                <label><input type="radio" name="theme" value="System" checked="@(appearanceTheme == "System")" @onchange='() => appearanceTheme = "System"' /> System</label>
            </div>
        </div>

        <div class="field">
            <label>Font Size</label>
            <div class="radio-group">
                <label><input type="radio" name="fontSize" value="Small" checked="@(appearanceFontSize == "Small")" @onchange='() => appearanceFontSize = "Small"' /> Small</label>
                <label><input type="radio" name="fontSize" value="Medium" checked="@(appearanceFontSize == "Medium")" @onchange='() => appearanceFontSize = "Medium"' /> Medium</label>
                <label><input type="radio" name="fontSize" value="Large" checked="@(appearanceFontSize == "Large")" @onchange='() => appearanceFontSize = "Large"' /> Large</label>
            </div>
        </div>

        <div class="field">
            <label for="language">Language</label>
            <select id="language" @bind="appearanceLanguage">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-row">
                <span>Compact Mode</span>
                <input type="checkbox" @bind="appearanceCompact" />
            </label>
        </div>

        <div class="preview-area @(appearanceTheme == "Dark" ? "preview-dark" : "preview-light") @(appearanceCompact ? "preview-compact" : "")"
             style="font-size: @GetPreviewFontSize()">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p><strong>Theme:</strong> @appearanceTheme | <strong>Font:</strong> @appearanceFontSize | <strong>Language:</strong> @appearanceLanguage</p>
            <button class="btn-preview">Sample Button</button>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </section>
};}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileDisplayName_AvatarUrl = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifDigest;
    private List<string> mutedChannels = new();
    private List<string> allChannels = new();

    // Security state
    private SecuritySettings? securitySettings;
    private bool twoFactorEnabled;
    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string currentSessionId = "sess-1";
    private bool showRevokeConfirm;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "Light";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "English";
    private bool appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        isLoading = false;
    }

    private async Task LoadAllData()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        notifEmail = notifs.EmailNotifications;
        notifPush = notifs.PushNotifications;
        notifDigest = notifs.WeeklyDigest;
        mutedChannels = new List<string>(notifs.MutedChannels);
        allChannels = new List<string>(notifs.MutedChannels);

        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompact = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
        profileDisplayName_AvatarUrl = profile.AvatarUrl;
    }

    private void SetSection(string section)
    {
        activeSection = section;
        toastMessage = null;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileDisplayName_AvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            ApplyProfile(savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications actions
    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmail, notifPush, notifDigest, new List<string>(mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        passwordPanelOpen = false;
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirm = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        showRevokeConfirm = false;
        sessionToRevoke = null;
        ShowToast("Session revoked.", "success");
    }

    // Appearance actions
    private string GetPreviewFontSize() => appearanceFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompact);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToast();
    }

    private async Task DismissToast()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}
