@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileDisplayName_AvatarUrl = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifDigest;
    private List<string> mutedChannels = new();
    private List<string> allChannels = new();

    // Security state
    private SecuritySettings? securitySettings;
    private bool twoFactorEnabled;
    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string currentSessionId = "sess-1";
    private bool showRevokeConfirm;
    private ActiveSession? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "Light";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "English";
    private bool appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        isLoading = false;
    }

    private async Task LoadAllData()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        notifEmail = notifs.EmailNotifications;
        notifPush = notifs.PushNotifications;
        notifDigest = notifs.WeeklyDigest;
        mutedChannels = new List<string>(notifs.MutedChannels);
        allChannels = new List<string>(notifs.MutedChannels);

        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        appearanceTheme = appearance.Theme;
        appearanceFontSize = appearance.FontSize;
        appearanceLanguage = appearance.Language;
        appearanceCompact = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
        profileDisplayName_AvatarUrl = profile.AvatarUrl;
    }

    private void SetSection(string section)
    {
        activeSection = section;
        toastMessage = null;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileDisplayName_AvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            ApplyProfile(savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications actions
    private bool IsChannelMuted(string channel) => mutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!muted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmail, notifPush, notifDigest, new List<string>(mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        passwordPanelOpen = false;
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirm = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        showRevokeConfirm = false;
        sessionToRevoke = null;
        ShowToast("Session revoked.", "success");
    }

    // Appearance actions
    private string GetPreviewFontSize() => appearanceFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompact);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToast();
    }

    private async Task DismissToast()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

